head.script:
scwin.screenId = "jldfil25900";

///////// 1. 변수 및 선언 영역 /////////

scwin.modifiyDate = "N";


///////// 2. 초기화 영역 /////////

// 현재 시각 파생값 충전 — as-is JSP 계산분(서버 데이터 아님). 진입점 선두 단계.
/**
 * @method
 * @name scwin.init_nowVars
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.init_nowVars = function () {
    let __pc = $c.util.getComponent('dma_pageContext');
    if (!__pc || !__pc.set || !__pc.get) { return; }
    if (!__pc.get("sysYear")) { __pc.set("sysYear", $c.date.getServerDateTime("yyyy")); }
};

// 속성 EL 실현 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_attrReals
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.init_attrReals = function () {
    let __attrReals = [{ childId: "td_16", attr: "__html", fn: function () { return ([String(String($c.data.readValue("dma_pageContext", "sysYear", { silent: true }))), String((String($c.data.readValue("dma_pageContext", "sysYear", { silent: true })) - 1))].some(function (__v) { return String(__v == null ? '' : __v).trim() !== ''; }) ? ("『배당기준일자 신고』작성하는 화면입니다.<br/> <span style=\"color:red\">" + String(String($c.data.readValue("dma_pageContext", "sysYear", { silent: true }))) + "</span>년도 배당기준일 신고는 반드시 <span style=\"color:red\">작성하기</span> 버튼을 눌러서 제출해주시기 바랍니다. (※ " + String((String($c.data.readValue("dma_pageContext", "sysYear", { silent: true })) - 1)) + "년도 신고내용 수정·제출 금지)") : ''); } }];
    $c.util.applyAttrReals(__attrReals);
};

// 런타임 분기 평가 — 공용 $c.util.evalConds (화면은 조건 바인딩 목록만 보유)
// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = function () {
    let binds = [{ id: "btn_goWrite", fn: function(){ return ($c.data.readValue("dma_pageContext", "listStatCd", { ctx: true, label: "listStatCd" }) ==='Y'); } }];
    $c.util.evalConds(binds);
};

// 화면 전환 파라미터 수신 — 공용 $c.data.recvParamData (§106, 이름 고정 "paramData"; 실패 표출은 gcc 함수 몫). onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { $c.data.recvParamData('dma_pageContext'); };

// as-is 흐름 보존 — 스켈레톤이 대체한 함수가 쓰던 전역 선언
scwin.result = undefined; scwin.modifiyDate = undefined;

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_nowVars();
        scwin.init_attrReals();
        scwin.init_conds();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil25900.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_goWrite_onclick
 * @author Inswave
 * @date 2026. 09. 06
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_goWrite_onclick = async function(e){
    try { let ev = e; let event = ev; let __self = (ev && (ev.element || ev.target || ev.srcElement)) || this; await scwin.fn_goWrite() 
    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil25900.btn_goWrite_onclick' }); }
};

/**
 * @event
 * @name scwin.grd_dividendDateList_oncellclick
 * @author Inswave
 * @date 2026. 09. 06
 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_dividendDateList_oncellclick = async function (rowIndex, columnIndex, columnId) { try { let dl = $c.util.getComponent('dlt_dividendDateList'); let r = dl && dl.getRowJSON ? dl.getRowJSON(rowIndex) : null; if (!r) { return; } await scwin.fn_goView(r["bzProcsNo"], r["basYy"]); return; } catch (e) { await $c.exception.handleError(e, { notify: 'none', context: 'grd_dividendDateList.oncellclick' }); } };


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_modifiyDate
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_modifiyDate = async function () {
    const sbmOptions = {
        id: "tx_fn_modifiyDate",
        method: "post",
        action: "dividendBaseDate.do",
        ref: "dma_modifiyDateReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { notify: 'none', context: "jldfil25900.tx_fn_modifiyDate" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        if (res && res.responseJSON && res.responseJSON.message) { await $c.win.alert(res.responseJSON.message); }
        return res;
    }
    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.fn_goWrite
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.fn_goWrite = async function () {
    await scwin.fn_modifiyDate();
    if (scwin.modifiyDate === "N") {
        await $c.win.alert("작성기간이 아닙니다.");
        return;
    }
    if (scwin.modifiyDate === "U") {
        await $c.win.alert("작성중인 배당기준일자 신고가 있습니다.");
        return;
    }
    $("input[name='method']").val("dividendDateModifiy");
    $("input[name='status']").val("R");
    $("form[name='dividendDateForm']").attr("action", "dividendBaseDate.do");
    $c.win.moveUrl("/jldfil25910/jldfil25910.xml", { "method": "dividendDateModifiy", "status": "R" });
};


/**
 * @method
 * @name scwin.fn_goView
 * @author Inswave
 * @date 2026. 09. 06
 * @param ipt_bzProcsNo basYear
 * @returns
 * @hidden N
*/
scwin.fn_goView = async function (ipt_bzProcsNo, basYear) {
    $("input[name='method']").val("dividendDateModifiy");
    $("input[name='status']").val(await scwin.fn_modifiyDate());
    $("input[name='bzProcsNo']").val(ipt_bzProcsNo);
    $("form[name='dividendDateForm']").attr("action", "dividendBaseDate.do");
    $c.win.moveUrl("/jldfil25910/jldfil25910.xml", { "method": "dividendDateModifiy", "bzProcsNo": ipt_bzProcsNo });
};


// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)
/**
 * @method
 * @name scwin.fn_modifiyDate_done
 * @author Inswave
 * @date 2026. 09. 06
 * @param data
 * @returns
 * @hidden N
*/
scwin.fn_modifiyDate_done = function (data) {scwin.result = JSON.parse(data);
    scwin.modifiyDate = scwin.result.checkModifiyDate;
};

/**
 * @method
 * @name scwin.fn_modifiyDate
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.fn_modifiyDate = async function () { const __r = await scwin.tx_fn_modifiyDate(); try { scwin.fn_modifiyDate_done.call(window, JSON.stringify((__r && __r.responseJSON && (__r.responseJSON.body != null ? __r.responseJSON.body : __r.responseJSON)) || {})); } catch (_se) { await $c.exception.handleError(_se, { notify: 'none', context: 'jldfil25900.fn_modifiyDate' }); } return __r; };
